/// <summary>
/// MPJ_28153 Interbranch Transfers	DCP 01/08/2022
/// </summary>
[ExtensionOf(formDataSourceStr(InventTransferOrders, InventTransferTable))]
final class METInventTransferOrdersFormDS_Extension
{
}

Method.Source:
    /// <summary>
    /// Write the record
    /// </summary>
    void write()
    {
        FormDataSource              metInventTransferTableExt_ds;
        METInventTransferTableExt   metInventTransferTableExt;
        InventTransferTable         metInventTransferTable;

        next write();

        metInventTransferTableExt_ds = this.formRun().dataSource(formDataSourceStr(InventTransferOrders, METInventTransferTableExt));

        if (metInventTransferTableExt_ds)
        {
            metInventTransferTable      = this.cursor();
            metInventTransferTableExt   = metInventTransferTableExt_ds.cursor();
            
            metInventTransferTable.metPackMETInventTransferTableExt(metInventTransferTableExt);
            metInventTransferTableExt.SysExtensionSerializerExtensionMap::insertAfterBaseTable(metInventTransferTable);
        }

    }

    /// <summary>
    /// CB627_TMSEngineProcessingTOCreation
    /// active method
    /// </summary>
    /// <returns>int</returns>
    public int active()
    {
        int         ret;
        boolean     isAllowEdit;

        ret = next active();

        InventTransferTable         metTransferTable      = this.cursor();
        METInventTransferTableExt   metTransferTableExt   = metTransferTable.metInventTransferTableExt();

        isAllowEdit = metTransferTableExt.OrderExtractStatus != METOrderExtractStatus::Open;
        
        FormControl   btnControl = this.formRun().design().controlName(menuItemActionStr(METTMSEngineTransferOrderProcess));
        
        btnControl.allowEdit(isAllowEdit);

        return ret;
    }
